goals.split_s:
(∀ {X : Type u} [TopologicalSpace X] {ι : Type u} [Countable ι] {π : ι → Type u}
    [inst : (i : ι) → TopologicalSpace (π i)], (∀ (i : ι), ∃ S, S.Countable ∧ Dense S) → ∃ S, S.Countable ∧ Dense S) ↔
  True →
    ∀ {X : Type u} [TopologicalSpace X] {ι : Type u} [Countable ι] {π : ι → Type u}
      [inst : (i : ι) → TopologicalSpace (π i)], (∀ (i : ι), ∃ S, S.Countable ∧ Dense S) → ∃ S, S.Countable ∧ Dense S

(∀ {X : Type u} [inst : TopologicalSpace X] [T2Space X] {f : X → ℝ},
    Continuous f → IsClosed {p | f p = 0}) ↔
  True → ∀ {X : Type u} [inst : TopologicalSpace X] [T2Space X] {f : X → ℝ}, Continuous f → IsClosed {p | f p = 0}

goals.ncomp:
¬∀ {n : ℤ},
    Irreducible 2 ∧ Irreducible { re := 0, im := 1 } ∧ Irreducible (1 + { re := 0, im := 1 }) ↔
      Irreducible 2 ∧ Irreducible { re := 0, im := 1 } ∧ Irreducible { re := 1, im := 1 }

goals.split_s:
(∀ (n : ℤ),
    Squarefree n → 3 < n → Irreducible 2 ∧ Irreducible { re := 0, im := 1 } ∧ Irreducible { re := 1, im := 1 }) ↔
  ∀ (n : ℤ), Squarefree n ∧ 3 < n → Irreducible 2 ∧ Irreducible { re := 0, im := 1 } ∧ Irreducible { re := 1, im := 1 }

(∀ (S : Set (Set ℝ)),
    S = {s | ∃ a b, a < b ∧ s = {x | ↑a < x ∧ x < ↑b}} → IsTopologicalBasis S) ↔
  True → IsTopologicalBasis {s | ∃ a b, a < b ∧ s = {x | ↑a < x ∧ x < ↑b}}

(∀ {X : Type u} [inst : MetricSpace X] [T2Space X] {f : X → ℝ},
    Continuous f → IsClosed {p | f p = 0}) ↔
  True → ∀ {X : Type u} [inst : MetricSpace X] [T2Space X] {f : X → ℝ}, Continuous f → IsClosed {p | f p = 0}

(∀ {V : Type u} [inst : AddCommGroup V] [inst_1 : Module ℂ V] {W : Subspace ℂ V}
    {X : Subspace ℂ V} {Y : Subspace ℂ V}, W + Y = ⊤ → W ≤ Y ∨ Y ≤ W) ↔
  True →
    ∀ {V : Type u} [inst : AddCommGroup V] [inst_1 : Module ℂ V] {W : Subspace ℂ V} {X : Subspace ℂ V}
      {Y : Subspace ℂ V}, W + Y = ⊤ → W ≤ Y ∨ Y ≤ W

goals.nhyp:
¬∀ {X : Type u} [inst : TopologicalSpace X] {Y : Type u} [inst_1 : TopologicalSpace Y] {A : Set X}
    {f : X → Y},
    T2Space Y ∧ ContinuousOn f A ↔ T2Space Y ∧ IsClosed A ∧ ContinuousOn f A ∧ ∀ x ∈ A, ContinuousWithinAt f A x
